contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint[] memory v) public {
        require(tos.length > 0);
        require(tos.length == v.length);

        bool succeeded = false;
        bytes memory observed;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            require(r);
            succeeded = true;
        } catch {
            observed = bytes("");
        }

        if (succeeded) {
            for (uint i = 0; i < tos.length; i++) {
                bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
                bytes memory expected = abi.encodeWithSelector(id, from, tos[i], v[i]);
                (bool ok, bytes memory data) = caddress.staticcall(expected);
                require(ok);
                require(keccak256(data) == keccak256(observed));
            }
        }

        assert(succeeded || address(this).balance >= 0);
    }

    receive() external payable {}
}

