contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool firstFailed = false;
        bool allFailed = true;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));

        for (uint i = 0; i < _tos.length; i++) {
            (bool s, ) = caddress.staticcall(abi.encodeWithSelector(id, from, _tos[i], v[i]));
            if (!s && !firstFailed) {
                firstFailed = true;
            }
            if (s) {
                allFailed = false;
            }
        }

        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !allFailed);
    }

    receive() external payable {}
}

